return ['domain'=>'zinn-campaigns','plural-forms'=>'nplurals=3; plural=(n==1 ? 0 : n==0 || (n%100>0 && n%100<20) ? 1 : 2);','language'=>'ro_RO','project-id-version'=>'zinn-campaigns','pot-creation-date'=>'2026-11-12T11:23:33+00:00','po-revision-date'=>'2026-11-12T11:23:33+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Campaigns – Email & SMS Marketing for WooCommerce & More'=>'Zinn® Campaigns – Email & SMS Marketing for WooCommerce & More','https://zinndigital.com/wordpress-plugins/zinn-campaigns'=>'https://zinndigital.com/wordpress-plugins/zinn-campaigns','Connect your WordPress site or WooCommerce store to Zinn® Campaigns in one click and grow your list with double opt-in sign-up forms. Email, SMS and WhatsApp campaigns are sent from your Zinn® Campaigns account.'=>'Conectează-ți site-ul WordPress sau magazinul WooCommerce la Zinn® Campaigns cu un singur clic și dezvoltă-ți lista cu formulare de abonare cu dublă confirmare. Campaniile prin e-mail, SMS și WhatsApp sunt trimise din contul tău Zinn® Campaigns.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Zinn® Campaigns'=>'Zinn® Campaigns','You are not allowed to manage Zinn® Campaigns on this site.'=>'Nu ai permisiunea de a gestiona Zinn® Campaigns pe acest site.','This site is connected to Zinn® Campaigns.'=>'Acest site este conectat la Zinn® Campaigns.','This site is disconnected. Sign-up forms stop sending new sign-ups to Zinn® Campaigns.'=>'Acest site este deconectat. Formularele de înscriere nu mai trimit înscrieri noi către Zinn® Campaigns.','That connection took too long or was started in another browser. Press Connect again.'=>'Acea conexiune a durat prea mult sau a fost inițiată într-un alt navigator. Apasă din nou pe Conectează.','Zinn® did not accept the connection. Press Connect again; if it keeps failing, contact Zinn® support.'=>'Zinn® nu a acceptat conexiunea. Apasă din nou pe Conectare; dacă